"""Generate the environment reference from the same Pydantic settings declarations."""

import json
from typing import Any

from pydantic import BaseModel, SecretStr

from myapp.core.config import Settings


def environment_example() -> str:
    lines = [
        "# Generated by uv run project-env; do not edit by hand.",
        "# Development defaults only. Nested names use APP_ and __; lists/maps use JSON.",
    ]

    def render(model: type[BaseModel], prefix: str) -> None:
        for name, info in model.model_fields.items():
            annotation: Any = info.annotation
            key = prefix + name.upper()
            if isinstance(annotation, type) and issubclass(annotation, BaseModel):
                render(annotation, key + "__")
                continue
            value = info.get_default(call_default_factory=True)
            if value is None:
                lines.append(f"# {key}=  # optional, unset by default")
                continue
            if isinstance(value, SecretStr):
                value = value.get_secret_value()  # Declaration defaults only, never live Settings.
            if info.description:
                lines.append("# " + info.description.replace("\n", " "))
            if isinstance(value, (list, dict, set, frozenset, bool)) or value is None:
                value = json.dumps(sorted(value) if isinstance(value, (set, frozenset)) else value)
            lines.append(f"{key}={value}")

    render(Settings, "APP_")
    return "\n".join(lines) + "\n"
